 ph:[
  Ph(0,'1789 : des droits pour les citoyens','Pendant la Révolution, la Déclaration des droits de l’homme et du citoyen affirme : « Les hommes naissent et demeurent libres et égaux en droits. »','fra'),
  Ph(7,'Et les femmes ?','En 1791, Olympe de Gouges écrit une Déclaration des droits de la femme et de la citoyenne. L’égalité entre les femmes et les hommes mettra longtemps à avancer.','pap'),
  Ph(14,'1948 : des droits pour tous les humains','Après la Seconde Guerre mondiale, l’ONU adopte à Paris la Déclaration universelle des droits de l’homme. René Cassin, un juriste français, a participé à sa rédaction.','eur'),
  Ph(20,'Faire respecter ces droits','En Europe, la Cour européenne des droits de l’homme, à Strasbourg, juge les États qui ne respectent pas ces droits.','eur'),
  Ph(27,'1989 : les droits de l’enfant','La Convention internationale des droits de l’enfant est adoptée à l’ONU, à New York, le 20 novembre 1989. Presque tous les pays l’ont ratifiée, sauf les États-Unis.','kan'),
  Ph(34,'Quels droits ?','Avoir un nom et une nationalité, aller à l’école, être soigné, être protégé contre la violence et le travail forcé, jouer, donner son avis sur ce qui nous concerne.','kan'),
  Ph(42,'1981 : la fin de la peine de mort','En France, la peine de mort est abolie en 1981, à l’initiative de Robert Badinter. Aujourd’hui, plus des deux tiers des pays l’ont abolie dans leur loi ou ne l’appliquent plus.','fra'),
  Ph(52,'Partout, les mêmes droits','Ces textes valent aussi en Nouvelle-Calédonie : chaque enfant a droit à l’école, aux soins et à la protection.','kan')
 ],
 photos:[Sh('ddhc',1,7,'tr',2,'contain'),Sh('gouges',7,13,'bl',-2,'contain'),Sh('dudh',14,20,'tr',2,'contain'),Sh('cedh',20,26,'bl',-2)],
 legend:[['fra','France'],['eur','Lieu lié aux droits humains'],['kan','Droits de l’enfant']],
 mots:[['Déclaration','Texte solennel qui affirme des principes, comme des droits.'],['Droit','Ce que la loi permet ou garantit à chacun.'],['Convention','Accord signé par des pays, qui s’engagent à le respecter.'],['Ratifier','Pour un pays : accepter officiellement de respecter un traité.']],
