 ph:[
  Ph(0,'1882 : l’école laïque','Avec les lois Jules Ferry, l’école publique devient gratuite, obligatoire et laïque : on n’y enseigne pas de religion.','fra'),
  Ph(7,'1905 : la séparation','La loi du 9 décembre 1905 sépare les Églises et l’État. La République garantit la liberté de conscience ; elle ne reconnaît et ne paie aucun culte.','fra'),
  Ph(14,'Qu’est-ce que la laïcité ?','C’est la liberté de croire ou de ne pas croire, l’égalité de tous quelle que soit leur religion, et la neutralité de l’État. La Constitution dit que la France est une République laïque.','fra'),
  Ph(22,'Une exception : l’Alsace-Moselle','En 1905, l’Alsace et la Moselle étaient allemandes. Redevenues françaises en 1918, elles gardent le Concordat de 1801 : l’État y paie encore des prêtres, des pasteurs et des rabbins.','esp'),
  Ph(32,'Outre-mer : d’autres règles','En Guyane, une ordonnance de 1828 s’applique encore. En Nouvelle-Calédonie, en Polynésie française, à Wallis-et-Futuna ou à Mayotte, ce sont les décrets Mandel de 1939 : la loi de 1905 ne s’y applique pas.','kan'),
  Ph(42,'L’école en Nouvelle-Calédonie','L’école publique y est laïque. Beaucoup d’élèves vont aussi dans des écoles privées catholiques ou protestantes, sous contrat avec les pouvoirs publics.','kan'),
  Ph(50,'Vivre ensemble','La laïcité permet à des personnes de croyances différentes, ou sans religion, de vivre ensemble avec les mêmes droits. À l’école publique, la Charte de la laïcité l’explique en 15 articles.','fra')
 ],
 photos:[Sh('ferry',1,7,'tr',2,'contain'),Sh('briand',7,14,'bl',-2,'contain'),Sh('ecolepublique',14,21,'tr',2),Sh('strasbourg',24,31,'bl',-2)],
 legend:[['fra','Loi de 1905'],['esp','Concordat (Alsace-Moselle)'],['kan','Autres régimes (outre-mer)']],
 mots:[['Laïcité','Principe qui sépare les religions et l’État, garantit la liberté de croire ou non et l’égalité de tous.'],['Liberté de conscience','Liberté de croire, de ne pas croire ou de changer de religion.'],['Neutralité','L’État et ses agents ne favorisent aucune religion.'],['Concordat','Accord de 1801 entre la France et le pape, encore appliqué en Alsace-Moselle.']],
 q:[['Quelle loi sépare les Églises et l’État ?','La loi du 9 décembre 1905.'],['Qu’est-ce que la liberté de conscience ?','La liberté de croire ou de ne pas croire.'],['Où le Concordat s’applique-t-il encore en métropole ?','En Alsace-Moselle.'],['Quels textes organisent les cultes en Nouvelle-Calédonie ?','Les décrets Mandel de 1939.']],
