 ph:[
  Ph(0,'La solidarité près de chez soi','Dans chaque commune, on aide ceux qui en ont besoin. En Nouvelle-Calédonie, la CAFAT aide à payer les soins, les retraites et les allocations ; des associations comme la Croix-Rouge aident aussi.','kan'),
  Ph(11,'Aider nos voisins','Quand une catastrophe frappe un pays voisin, la France envoie de l’aide depuis la Nouvelle-Calédonie : après le cyclone Pam au Vanuatu (2015), le cyclone Winston aux Fidji (2016) ou l’éruption du volcan Hunga Tonga (2022).','pol'),
  Ph(19,'Un accord entre voisins','Depuis 1992, la France, l’Australie et la Nouvelle-Zélande organisent ensemble les secours dans le Pacifique : c’est l’accord FRANZ. Les militaires stationnés en Nouvelle-Calédonie y participent.','aus'),
  Ph(25,'Coopérer dans le Pacifique','La Communauté du Pacifique, qui a son siège à Nouméa, aide les pays de la région (santé, pêche, agriculture, climat). La Nouvelle-Calédonie est aussi membre du Forum des îles du Pacifique.','kan'),
  Ph(35,'L’ONU','Créée en 1945 pour maintenir la paix, l’Organisation des Nations unies réunit 193 pays. Son siège est à New York.','eur'),
  Ph(45,'Des organisations pour aider','La Croix-Rouge, née à Genève en 1863, secourt les blessés et les victimes ; le Programme alimentaire mondial, basé à Rome, apporte de la nourriture ; l’UNICEF protège les enfants.','ame'),
  Ph(54,'Et toi ?','Solidarité, entraide, bénévolat : à l’école ou dans ta commune, tu peux aussi aider les autres (collecte, projet solidaire, conseil des élèves).','fra')
 ],
